void fillRCij(FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb, FArray2D<double>& s, 
               FArray2D<std::complex<double>>& aQQ_qb0, FArray2D<std::complex<double>>& aQQ_QQb0, 
               FArray2D<std::complex<double>>& RQQ_qb, FArray2D<std::complex<double>>& RQQ_QQb, 
               FArray2D<std::complex<double>>& CQQ_QQb, FArray2D<std::complex<double>>& CQQ_qb) {
  using namespace constants_mod;
  using namespace epinv_mod;
  using namespace epinv2_mod;
  using namespace mxpart_mod;
  using namespace nflav_mod;
  using namespace scale_mod;

  std::complex<double> fac;

  // Definition of helicity-dependent momenta
  const int q = 1, QQ = 2, qb = 3, QQb = 4, g = 5;
  const int r[2] = {q, qb};
  const int RR[2] = {QQ, QQb};

  // Statement function for 1/e*Pij
  auto epinvPij = [&](int i, int j) {
        return epinv + lnrat(musq, -s(i, j));
  };

  // Eq. (11)
  fac = -half*epinv*(11*xn-2*float(nflav));
  for (int i=1; i<=2; ++i) {
    for (int j=1; j<=2; ++j) {
      RQQ_qb(i,j) = fac * aQQ_qb0(i,j);
      RQQ_QQb(i,j) = fac * aQQ_QQb0(i,j);
    }
  }

  // Eq. (12)
  fac = two / 3.0 * (xn - float(nflav)) * epinvPij(qb, q) +
        3.0 / 2.0 / xn * (epinvPij(qb, q) + epinvPij(QQb, QQ)) +
        29.0 / 18.0 * xn + 13.0 / 2.0 / xn - 10.0 / 9.0 * float(nflav);
  for (int i=1; i<=2; ++i) {
    for (int j=1; j<=2; ++j) {
      CQQ_QQb(i,j) = fac * aQQ_QQb0(i,j);
    }
  }

  // Eq. (13)
  fac = two / 3.0 * (xn - float(nflav)) * epinvPij(QQb, QQ) +
        3.0 / 2.0 / xn * (epinvPij(qb, q) + epinvPij(QQb, QQ)) +
        29.0 / 18.0 * xn + 13.0 / 2.0 / xn - 10.0 / 9.0 * float(nflav);
  for (int i=1; i<=2; ++i) {
    for (int j=1; j<=2; ++j) {
      CQQ_qb(i,j) = fac * aQQ_qb0(i,j);
    }
  }

  return;
}

extern "C" {
  void fillRCij_wrapper(std::complex<double>* za, std::complex<double>* zb, 
                         double* s, std::complex<double>* aQQ_qb0, 
