// Amplitudes for 0 -> qb- g- q+ g+ g+ from:
// 'One-Loop Corrections to Two-Quark Three-Gluon Amplitudes'
//  Zvi Bern, Lance Dixon, David A. Kosower
// Published in: Nucl.Phys.B 437 (1995) 259-304,
// e-Print: hep-ph/9409393 [hep-ph]

#include <constants_mod.hpp>
#include <epinv_mod.hpp>
#include <epinv2_mod.hpp>
#include <mxpart_mod.hpp>
#include <scale_mod.hpp>
#include <sprods_com_mod.hpp>
#include <FArray.hpp>
#include <complex>
#include <Need.hpp>

void A5qbmgmqpgpgp(int j1, int j2, int j3, int j4, int j5,
                    FArray2D<std::complex<double>>& za,
                    FArray2D<std::complex<double>>& zb,
                    std::complex<double>& miA5tree,
                    std::complex<double>& AL,
                    std::complex<double>& ASUSY,
                    std::complex<double>& Af,
                    std::complex<double>& As) {

    using namespace constants_mod;
    using namespace epinv_mod;
    using namespace epinv2_mod;
    using namespace mxpart_mod;
    using namespace scale_mod;
    using namespace sprods_com_mod;

    std::complex<double> VSUSY, VL, Vggluon, Vg13;
    std::complex<double> FSUSY, FS, FL, Ffgluon, Ff;

    // Eq. (5.19)
    miA5tree = std::pow(za(j1,j2),3) * za(j3,j2)
        / (za(j1,j2) * za(j2,j3) * za(j3,j4) * za(j4,j5) * za(j5,j1));

    Vggluon = -five*epinv*epinv2
        - epinv*(lnrat(musq,-s(j1,j2)) + lnrat(musq,-s(j2,j3)) + lnrat(musq,-s(j3,j4))
                 + lnrat(musq,-s(j4,j5)) + lnrat(musq,-s(j5,j1)))
        - half*(std::pow(lnrat(musq,-s(j1,j2)),2) + std::pow(lnrat(musq,-s(j2,j3)),2) + std::pow(lnrat(musq,-s(j3,j4)),2)
                + std::pow(lnrat(musq,-s(j4,j5)),2) + std::pow(lnrat(musq,-s(j5,j1)),2))
        + lnrat(-s(j1,j2),-s(j2,j3))*lnrat(-s(j3,j4),-s(j4,j5))
        + lnrat(-s(j2,j3),-s(j3,j4))*lnrat(-s(j4,j5),-s(j5,j1))
        + lnrat(-s(j3,j4),-s(j4,j5))*lnrat(-s(j5,j1),-s(j1,j2))
        + lnrat(-s(j4,j5),-s(j5,j1))*lnrat(-s(j1,j2),-s(j2,j3))
        + lnrat(-s(j5,j1),-s(j1,j2))*lnrat(-s(j2,j3),-s(j3,j4))
        + five/six*pisq;
    Vg13 = Vggluon
        + epinv*epinv2 + epinv*lnrat(musq,-s(j1,j2)) + half*std::pow(lnrat(musq,-s(j1,j2)),2)
        + epinv*epinv2 + epinv*lnrat(musq,-s(j2,j3)) + half*std::pow(lnrat(musq,-s(j2,j3)),2);

    VSUSY = Vggluon - 3.0*epinv - 1.5*(lnrat(musq,-s(j2,j3)) + lnrat(musq,-s(j5,j1))) - 6.0;
    VL = Vg13 - 1.5*(epinv + lnrat(musq,-s(j2,j3))) - 3.0
        + Lsm1(-s(j3,j4),-s(j5,j1),-s(j2,j3),-s(j5,j1))
        + Lsm1(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4));

    // Eq. (5.20)
    FSUSY =
        1.5*za(j1,j2)*(za(j2,j3)*zb(j3,j4)*za(j4,j1) + za(j2,j4)*zb(j4,j5)*za(j5,j1))
        / (za(j3,j4)*za(j4,j5)*za(j5,j1))
        * L0(-s(j2,j3),-s(j5,j1)) / s(j5,j1);

    Ffgluon = FSUSY*za(j1,j2)/(3.0*za(j3,j2));

    FS = (1.0/3.0)*zb(j3,j4)*zb(j3,j5)/(zb(j1,j2)*zb(j2,j3)*za(j4,j5));

    FL = FS
        + 0.5*za(j1,j5)*std::pow(zb(j5,j4),2)*std::pow(za(j4,j2),2)/(za(j3,j4)*za(j4,j5))
          * L1(-s(j2,j3),-s(j5,j1))/std::pow(s(j5,j1),2)
        + 2.0*za(j1,j2)*za(j2,j4)*zb(j4,j5)*za(j5,j1)/(za(j3,j4)*za(j4,j5)*za(j5,j1))
          * L0(-s(j2,j3),-s(j5,j1))/s(j5,j1)
        + 0.5*zb(j4,j5)*zb(j3,j5)*zb(j1,j3)/(zb(j2,j3)*zb(j1,j2)*zb(j1,j5)*za(j4,j5));

    Ff = czip;

    AL = VL*miA5tree + FL;
    ASUSY = VSUSY*miA5tree + FSUSY;
    // Vs = Vf =0, per Eq. (5.10)
    Af = Ff;
    As = FS;

    return;
}

extern "C" {
    void A5qbmgmqpgpgp_wrapper(int j1, int j2, int j3, int j4, int j5,
                                std::complex<double>* za, std::complex<double>* zb,
                                std::complex<double>* miA5tree,
                                std::complex<double>* AL, std::complex<double>* ASUSY,
                                std::complex<double>* Af, std::complex<double>* As) {

        using namespace mxpart_mod;

        FArray2D<std::complex<double>> za_array(za, mxpart, mxpart);
        FArray2D<std::complex<double>> zb_array(zb, mxpart, mxpart);

        A5qbmgmqpgpgp(j1, j2, j3, j4, j5, za_array, zb_array,
                      *miA5tree, *AL, *ASUSY, *Af, *As);
    }
}

