                + std::pow(lnrat(musq,-s(j4,j5)),2) + std::pow(lnrat(musq,-s(j5,j1)),2))
        + lnrat(-s(j1,j2),-s(j2,j3))*lnrat(-s(j3,j4),-s(j4,j5))
        + lnrat(-s(j2,j3),-s(j3,j4))*lnrat(-s(j4,j5),-s(j5,j1))
        + lnrat(-s(j3,j4),-s(j4,j5))*lnrat(-s(j5,j1),-s(j1,j2))
        + lnrat(-s(j4,j5),-s(j5,j1))*lnrat(-s(j1,j2),-s(j2,j3))
        + lnrat(-s(j5,j1),-s(j1,j2))*lnrat(-s(j2,j3),-s(j3,j4))
        + five/six*pisq;
    Vg13 = Vggluon
        + epinv*epinv2 + epinv*lnrat(musq,-s(j1,j2)) + half*std::pow(lnrat(musq,-s(j1,j2)),2)
        + epinv*epinv2 + epinv*lnrat(musq,-s(j2,j3)) + half*std::pow(lnrat(musq,-s(j2,j3)),2);

    VSUSY = Vggluon - 3.0*epinv - 1.5*(lnrat(musq,-s(j1,j2)) + lnrat(musq,-s(j4,j5))) - 6.0;
    VL = Vg13 - 1.5*(epinv + lnrat(musq,-s(j1,j2))) - 3.0
        + Lsm1(-s(j2,j3),-s(j4,j5),-s(j1,j2),-s(j4,j5));

    // Eq. (5.24)
    FSUSY =
        1.5*za(j1,j5)*za(j3,j5)
        * (za(j5,j4)*zb(j4,j3)*za(j3,j1) + za(j5,j3)*zb(j3,j2)*za(j2,j1))
        / (za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j5))
        * L0(-s(j1,j2),-s(j4,j5)) / s(j4,j5);

    Ffgluon = FSUSY*za(j1,j5)/(3.0*za(j3,j5));

    FL =
        std::pow(za(j1,j5),2)*zb(j2,j4)/(za(j1,j2)*za(j3,j4))
          * Ls0(-s(j3,j4),-s(j5,j1),-s(j2,j3),-s(j5,j1)) / s(j5,j1)
        + std::pow(za(j1,j5),2)*za(j1,j3)*zb(j1,j4)/(za(j1,j2)*za(j2,j3)*za(j3,j4))
          * Ls0(-s(j5,j1),-s(j2,j3),-s(j4,j5),-s(j2,j3)) / s(j2,j3)
        - 0.5*za(j3,j5)*za(j4,j5)*std::pow(zb(j3,j4),2)*std::pow(za(j1,j3),2)
          / (za(j1,j2)*za(j2,j3)*za(j3,j4))
          * L1(-s(j1,j2),-s(j4,j5)) / std::pow(s(j4,j5),2)
        - 2.0*za(j1,j5)*za(j3,j5)*za(j1,j3)*zb(j3,j4)/(za(j1,j2)*za(j2,j3)*za(j3,j4))
          * L0(-s(j1,j2),-s(j4,j5)) / s(j4,j5)
        - 0.5*std::pow(zb(j2,j4),2)/(za(j3,j4)*zb(j1,j5)*zb(j4,j5));

    FS = czip;

    Ff = czip;

    AL = VL*miA5tree + FL; // @coverage-probe
    ASUSY = VSUSY*miA5tree + FSUSY;
    // Vs = Vf =0, per Eq. (5.10)
    Af = Ff;
    As = FS;

    return;
}

extern "C" {
    void A5qbmgpqpgpgm_wrapper(int j1, int j2, int j3, int j4, int j5,
                                std::complex<double>* za, std::complex<double>* zb,
                                std::complex<double>* miA5tree,
                                std::complex<double>* AL, std::complex<double>* ASUSY,
                                std::complex<double>* Af, std::complex<double>* As) {

        using namespace mxpart_mod;

        FArray2D<std::complex<double>> za_array(za, mxpart, mxpart);
        FArray2D<std::complex<double>> zb_array(zb, mxpart, mxpart);

        A5qbmgpqpgpgm(j1, j2, j3, j4, j5, za_array, zb_array,
                      *miA5tree, *AL, *ASUSY, *Af, *As);
    }
}
